    [Serializable] public sealed class CompletionPlan { public int schemaVersion,postImportRewrittenBodies;public string kind,originalFailedReportPath,originalFailedReportSha256,sourcePlanPath,sourcePlanSha256,canonicalSha256,previewsSha256;public bool actualAssetsModified;public CompletedTarget[] targets;public CompletedImage[] previewImages; }
    [Serializable] public sealed class CanonicalFile { public string path,sha256,guid;public long bytes; }
    [Serializable] public sealed class CanonicalProduct { public string id,folder,status;public CanonicalFile[] files; }
    [Serializable] public sealed class CanonicalManifest { public string stageRoot;public CanonicalProduct[] products; }
    [Serializable] public sealed class CompletionReport
    {
        public int schemaVersion=1,materialsVerified,metadataGuidsVerified,sourceBackupsVerified,previewImagesVerified,vertexColorModelsVerified,observedUnityErrors,materialsWrittenByVerification;
        public string kind="bounded-missing-shader-completion-verification",status="checking",startedUtc,completedUtc,project,runDirectory,verificationPlanSha256=CompletionPlanSha,originalFailedReportPath,originalFailedReportSha256,sourceRepairPlanSha256,manifestSha256,previewsSha256;
        public bool sourceArchivesModified,originalSourcesModified,scenesOpened,projectSettingsModified,originalFailedEvidenceModified;
        public List<Result> materials=new List<Result>();public List<string> errors=new List<string>();
    }
    static void VerifyCurrentCanonical(string manifestPath,Plan plan,CompletionPlan verification)
    {
        var current=JsonUtility.FromJson<CanonicalManifest>(File.ReadAllText(manifestPath));if(current.products==null||current.products.Length!=84||current.products.Select(p=>p.id).Distinct().Count()!=84||current.products.Any(p=>p.status!="complete")||!YamyamAssetLibraryIO.NormalPath(current.stageRoot).Equals(YamyamAssetLibraryIO.NormalPath(Absolute(Root.TrimEnd('/'))),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Current exact84-product owned canonical context is unavailable.");
        foreach(var expected in verification.targets){var target=plan.targets.Single(t=>t.body.assetPath==expected.assetPath);string relative=expected.assetPath.Substring(Root.Length);var owners=current.products.Where(p=>relative.StartsWith(p.folder+"/",StringComparison.Ordinal)).ToArray();if(owners.Length!=1)throw new InvalidDataException("Current material has no unique product owner.");var body=owners[0].files.Where(f=>f.path==relative).ToArray();var metadata=owners[0].files.Where(f=>f.path==relative+".meta").ToArray();if(body.Length!=1||metadata.Length!=1||metadata[0].guid!=target.metadata.guid||metadata[0].sha256!=target.metadata.sha256||metadata[0].bytes!=target.metadata.bytes||!((body[0].sha256==target.body.sha256&&body[0].bytes==target.body.bytes)||(body[0].sha256==expected.currentSha256&&body[0].bytes==expected.currentBytes)))throw new InvalidDataException("Current canonical changed a reviewed material/meta identity instead of only unrelated bookkeeping.");}
    }
    static void VerifyCompleted()
    {
        Guard();if(EditorApplication.isCompiling||EditorApplication.isUpdating)throw new InvalidOperationException("Editor must be idle.");
        string local=Path.Combine(Project,"Library/YamyamAssetLibrary"),run=Path.Combine(local,"shader-repair-verification",DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ")+"-"+Guid.NewGuid().ToString("N"));NoLinks(run);Directory.CreateDirectory(run);
        var report=new CompletionReport{project=Project,runDirectory=run,startedUtc=Utc()};string reportPath=Path.Combine(run,"report.json");Action persist=()=>Atomic(reportPath,JsonUtility.ToJson(report,true));Application.LogCallback capture=(message,stack,type)=>{if(type==LogType.Error||type==LogType.Assert||type==LogType.Exception){report.observedUnityErrors++;report.errors.Add(message);}};Application.logMessageReceived+=capture;
        try{
            string verificationPath=Path.Combine(Work,"shader-repair-completion-verification-plan.json");NoLinks(verificationPath);if(HashFile(verificationPath)!=CompletionPlanSha)throw new InvalidDataException("Completion verification plan changed.");var verification=JsonUtility.FromJson<CompletionPlan>(File.ReadAllText(verificationPath));
            if(verification.schemaVersion!=1||verification.kind!="verify-already-applied35-shader-adaptations"||verification.actualAssetsModified||verification.targets==null||verification.targets.Length!=35||verification.targets.Select(t=>t.assetPath).Distinct().Count()!=35||verification.previewImages==null||verification.previewImages.Length!=84||verification.previewImages.Select(i=>i.id).Distinct().Count()!=84||verification.sourcePlanSha256!=PlanSha)throw new InvalidDataException("Unexpected completed-repair scope.");
            NoLinks(verification.originalFailedReportPath);NoLinks(verification.sourcePlanPath);if(HashFile(verification.originalFailedReportPath)!=verification.originalFailedReportSha256||HashFile(verification.sourcePlanPath)!=PlanSha)throw new InvalidDataException("Immutable failed run/plan changed.");
            var failed=JsonUtility.FromJson<Report>(File.ReadAllText(verification.originalFailedReportPath));var plan=JsonUtility.FromJson<Plan>(File.ReadAllText(verification.sourcePlanPath));
            if(failed.status!="failed"||failed.observedUnityErrors!=0||failed.materialsCompleted!=35||failed.hdrpMaterials!=34||failed.vertexAdaptations!=1||failed.vertexColorModelsVerified!=3||failed.materials.Count!=35||failed.materials.Any(r=>!r.complete||r.otherSavedBeforeSha256!=r.otherSavedAfterSha256)||failed.unaffectedPreviewRecordsVerified!=83||failed.unaffectedPreviewImagesVerified!=83||failed.errors.Count!=1||!failed.errors[0].StartsWith("System.IO.InvalidDataException: Record escaped exact owned asset path.",StringComparison.Ordinal)||failed.previewsAfterSha256!=verification.previewsSha256)throw new InvalidDataException("Only the exact terminal optional-record failure after35 completed native checks is recoverable here.");
            string manifestPath=Path.Combine(Work,"staging-manifest.json"),previewsPath=Path.Combine(local,"previews.json");NoLinks(manifestPath);NoLinks(previewsPath);if(HashFile(previewsPath)!=verification.previewsSha256||failed.manifestSha256!=verification.canonicalSha256)throw new InvalidDataException("Verification historical/preview context changed.");VerifyCurrentCanonical(manifestPath,plan,verification);
            report.originalFailedReportPath=verification.originalFailedReportPath;report.originalFailedReportSha256=verification.originalFailedReportSha256;report.sourceRepairPlanSha256=PlanSha;report.manifestSha256=HashFile(manifestPath);report.previewsSha256=verification.previewsSha256;
            File.Copy(verificationPath,Path.Combine(run,"verification-plan.json"),false);File.Copy(verification.originalFailedReportPath,Path.Combine(run,"original-failed-report.json"),false);File.Copy(verification.sourcePlanPath,Path.Combine(run,"original-source-plan.json"),false);
            foreach(var expected in verification.targets){
                Target target=plan.targets.Single(t=>t.body.assetPath==expected.assetPath);Result old=failed.materials.Single(r=>r.path==expected.assetPath);NoLinks(target.body.path);NoLinks(expected.originalBackupPath);
                if(!target.body.assetPath.StartsWith(Root,StringComparison.Ordinal)||!YamyamAssetLibraryIO.NormalPath(expected.originalBackupPath).Equals(YamyamAssetLibraryIO.NormalPath(Path.Combine(failed.runDirectory,"backups",target.body.assetPath.Substring(Root.Length).Replace('/',Path.DirectorySeparatorChar))),StringComparison.OrdinalIgnoreCase)||expected.originalBackupSha256!=target.body.sha256||HashFile(expected.originalBackupPath)!=target.body.sha256||HashFile(expected.originalBackupPath+".meta")!=target.metadata.sha256||old.guid!=target.metadata.guid||old.metadataSha256!=target.metadata.sha256||old.afterSha256!=expected.immediateAfterSha256)throw new InvalidDataException("Completed-target source backup or original identity differs.");
                if(HashFile(target.body.path)!=expected.currentSha256||new FileInfo(target.body.path).Length!=expected.currentBytes)throw new InvalidDataException("Current already-repaired material changed from reviewed semantic proof.");Exact(target.metadata);report.metadataGuidsVerified++;report.sourceBackupsVerified++;
                Texture texture=null;if(target.kind=="hdrp-lit"&&target.baseTextureFileId!="0"){Exact(target.baseTexture);Exact(target.baseTextureMetadata);texture=AssetDatabase.LoadAssetAtPath<Texture2D>(target.baseTexture.assetPath);if(!texture||ObjectId(texture)!=target.baseTextureGuid+":"+target.baseTextureFileId)throw new InvalidDataException("Repaired source map identity differs.");}else if(target.kind=="unused-vertex-color-adaptation"){Exact(target.vertexShader);Exact(target.vertexShaderMetadata);var native=new Report();VerifyVertexSources(target,native);report.vertexColorModelsVerified+=native.vertexColorModelsVerified;}
                Material material=AssetDatabase.LoadAssetAtPath<Material>(target.body.assetPath);if(!material)throw new InvalidDataException("Already repaired material did not load.");var all=RetainedSaved(material);if(expected.retainedSavedKeys==null||expected.retainedSavedKeys.Length!=old.preservedSavedProperties||expected.retainedSavedKeys.Distinct().Count()!=expected.retainedSavedKeys.Length||expected.retainedSavedKeys.Any(k=>!all.ContainsKey(k)))throw new InvalidDataException("Original retained property key set differs.");var retained=expected.retainedSavedKeys.ToDictionary(k=>k,k=>all[k],StringComparer.Ordinal);if(RetainedHash(retained)!=old.otherSavedBeforeSha256)throw new InvalidDataException("Current native unrelated source properties differ from the original successful preflight.");
                var result=new Result{path=old.path,guid=old.guid,kind=old.kind,sourceShaderGuid=old.sourceShaderGuid,beforeSha256=old.beforeSha256,afterSha256=expected.currentSha256,metadataSha256=old.metadataSha256,localId=old.localId,otherSavedBeforeSha256=old.otherSavedBeforeSha256,preservedSavedProperties=old.preservedSavedProperties,complete=true};var item=new Prepared{target=target,actual=material,baseTexture=texture,retained=retained,result=result};CheckNative(item,material,true);result.shader=material.shader.name;result.baseColor=material.GetVector("_BaseColor");result.linearEmission=target.kind=="hdrp-lit"?material.GetVector("_EmissionColor"):Vector4.zero;result.surface=target.surface;result.alphaClip=target.alphaClip;result.cull=target.cull;result.renderQueue=material.renderQueue;report.materials.Add(result);report.materialsVerified++;
            }
            foreach(var image in verification.previewImages){NoLinks(image.path);if(!YamyamAssetLibraryIO.NormalPath(image.path).StartsWith(YamyamAssetLibraryIO.NormalPath(Path.Combine(local,"previews"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||HashFile(image.path)!=image.sha256)throw new InvalidDataException("Current completed preview image changed.");report.previewImagesVerified++;}
            foreach(var expected in verification.targets){var target=plan.targets.Single(t=>t.body.assetPath==expected.assetPath);if(HashFile(target.body.path)!=expected.currentSha256)throw new InvalidDataException("Unity changed a material during verification; review rather than silently adopt.");Exact(target.metadata);}
            if(HashFile(manifestPath)!=report.manifestSha256||HashFile(previewsPath)!=verification.previewsSha256||HashFile(verification.originalFailedReportPath)!=verification.originalFailedReportSha256||report.materialsVerified!=35||report.vertexColorModelsVerified!=3||report.observedUnityErrors!=0)throw new InvalidDataException("Verification final count/context/native error check failed.");report.status="complete";
        }catch(Exception error){report.status="failed";report.errors.Add(error.ToString());throw;}
        finally{Application.logMessageReceived-=capture;report.completedUtc=Utc();persist();Atomic(Path.Combine(local,"shader-repair-verification-report.json"),JsonUtility.ToJson(report,true));}
    }
    public static void VerifyCompletedHeadless(){Guard();int exit=0;try{VerifyCompleted();}catch(Exception error){Debug.LogError(error);exit=1;}EditorApplication.Exit(exit);}
